#include <iostream>
#include <algorithm>

int main() {
    long R, C;
    std::cin >> R >> C;

    auto getResult = [](long r, long c) -> long {
        if (r < 3 && c < 3) return 0;
        if (r == 1) {
            long total = c;
            long m = c % 6;
            if (m != 0) {
                if (m <= 3) total -= m;
                else if (m == 4) total -= 2;
                else total -= 1;
            }
            return total;
        }
        if (r == 2) {
            if (c == 3 || c == 7) return r * (c - 1);
            return r * c;
        }
        long totalCells = r * c;
        if (totalCells % 2 == 0) return totalCells;
        return totalCells - 1;
    };

    long result = getResult(R, C);
    std::cout << result << std::endl;

    return 0;
}
